{"file_path":"src/evaluate.js","content":"/** Working out what each cell holds, and which cells each one names. */

import { parseAddress, expandRange, compareAddresses } from './address.js'
import { parseFormula, rangesWellPlaced } from './formula.js'
import {
  num,
  bool,
  err,
  DIV0,
  REF,
  VALUE,
  CYCLE,
  NAME,
  ERR,
  isError,
  asNumber,
