{"file_path":"src/parse.js","content":"/** Parsing of the election text into a candidate list and ballots. */

const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/

export class ParseError extends Error {}

function fail(message) {
  throw new ParseError(message)
}

/**
 * Parse the election. Returns { candidates, ballots } where a ballot is
 * { count, ranking } with ranking a list of candidate names.
 */
export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null
  const declared = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i += 1) {
    const lineNumber = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)
    const directive = words[0]
    const rest = words.slice(1)

    if (directive === 'candidates') {
      if (candidates !== null) {
        fail(`line ${lineNumber}: candidates must be declared once, before any ballot`)
      }
      if (rest.length === 0) fail(`line ${lineNumber}: expected candidates <name>...`)
      for (const name of rest) {
        if (!NAME.test(name)) fail(`line ${lineNumber}: invalid candidate name ${name}`)
        if (declared.has(name)) fail(`line ${lineNumber}: candidate ${name} is declared twice`)
        declared.add(name)
      }
      candidates = rest.slice()
    } else if (directive === 'ballot') {
      if (candidates === null) {
        fail(`line ${lineNumber}: candidates must be declared once, before any ballot`)
      }
      if (rest.length < 2) fail(`line ${lineNumber}: expected ballot <count> <candidate>...`)
      const count = rest[0]
      if (!COUNT.test(count)) fail(`line ${lineNumber}: count must be a positive integer`)
      const ranking = rest.slice(1)
      const seen = new Set()
      for (const name of ranking) {
        if (!declared.has(name)) fail(`line ${lineNumber}: unknown candidate ${name}`)
        if (seen.has(name)) fail(`line ${lineNumber}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: Number(count), ranking })
    } else {
      fail(`line ${lineNumber}: unknown directive ${directive}`)
    }
  }

  if (candidates === null) fail('no candidates')
  return { candidates, ballots }
}
"}

{"file_path":"src/count.js","content":"/** The instant-runoff count itself. */

/**
 * Run the count. Returns { rounds, winner } where each round is
 * { counts: Map<name, votes>, continuing: [names], exhausted, eliminated }.
 */
export function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const history = []

  for (;;) {
    const counts = new Map()
    for (const name of candidates) {
      if (continuing.has(name)) counts.set(name, 0)
    }
    let exhausted = 0
    let active = 0
    for (const ballot of ballots) {
      const choice = ballot.ranking.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
