{"file_path":"src/count.js","content":"/** The instant-runoff count itself. */

/**
 * Run the count. Returns { rounds, winner } where each round is
 * { counts: Map<name, votes>, continuing: [names], exhausted, eliminated }.
 */
export function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const history = []

  for (;;) {
    const counts = new Map()
    for (const name of candidates) {
      if (continuing.has(name)) counts.set(name, 0)
    }
    let exhausted = 0
    let active = 0
    for (const ballot of ballots) {
      const choice = ballot.ranking.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        counts.set(choice, counts.get(choice) + ballot.count)
        active += ballot.count
      }
    }

    const round = { counts, exhausted, eliminated: null }
    history.push(round)

    if (active === 0) return { rounds: history, winner: null }

    let winner = null
    for (const [name, votes] of counts) {
      if (votes * 2 > active) winner = name
    }
    if (winner !== null) return { rounds: history, winner }

    const loser = pickLoser(counts, history)
    round.eliminated = loser
    continuing.delete(loser)
  }
}

function pickLoser(counts, history) {
  const fewest = Math.min(...counts.values())
  let tied = [...counts.keys()].filter((name) => counts.get(name) === fewest)
  if (tied.length === 1) return tied[0]

  for (const round of history) {
    if (tied.length === 1) break
    const values = tied.map((name) => round.counts.get(name) ?? 0)
    const least = Math.min(...values)
    if (values.some((value) => value !== least)) {
      tied = tied.filter((name, index) => values[index] === least)
    }
  }
  if (tied.length === 1) return tied[0]

  let last = tied[0]
  for (const name of tied) {
    if (compareCodePoints(name, last) > 0) last = name
  }
  return last
}

function compareCodePoints(a, b) {
  if (a === b) return 0
  return a < b ? -1 : 1
}
"}

