{"file_path":"src/schedule.js","content":"/** The bounded worker simulation behind `pack`. */

import { compareNames, sortedNames } from './parse.js'
import { priorities } from './graph.js'

/**
 * Runs the graph on `workerCount` workers, greedily starting the ready task of
 * greatest priority (ties by ascending name) on the free worker of smallest
 * index. Returns the run of every worker and the makespan.
 */
export function pack(graph, workerCount) {
  const priority = priorities(graph)
  const names = sortedNames(graph)
  const runs = []
  const free = [] // the instant each worker next becomes free
  for (let i = 0; i < workerCount; i += 1) {
    runs.push([])
    free.push(0)
  }

  const dependents = new Map()
  const waiting = new Map() // name -> dependencies not finished yet
  const readyAt = new Map() // name -> the instant its dependencies are all done
  for (const name of names) {
    dependents.set(name, [])
    readyAt.set(name, 0)
  }
  for (const name of names) {
    const deps = graph.tasks.get(name).deps
    waiting.set(name, deps.length)
    for (const dependency of deps) dependents.get(dependency).push(name)
  }

  // Tasks whose dependencies have all finished, still to be started.
  const pool = names.filter((name) => waiting.get(name) === 0)
  let remaining = names.length
  let time = 0
  let makespan = 0

  while (remaining > 0) {
    for (;;) {
      const worker = free.findIndex((when) => when <= time)
      if (worker === -1) break
      const at = pickReady(pool, readyAt, priority, time)
      if (at === -1) break
      const name = pool[at]
      pool.splice(at, 1)
      const end = time + graph.tasks.get(name).cost
      runs[worker].push({ name, start: time, finish: end })
      free[worker] = end
      remaining -= 1
      if (end > makespan) makespan = end
      for (const child of dependents.get(name)) {
        if (end > readyAt.get(child)) readyAt.set(child, end)
        const left = waiting.get(child) - 1
        waiting.set(child, left)
        if (left === 0) pool.push(child)
      }
    }

    let next = null
    for (const when of free) {
      if (when > time && (next === null || when < next)) next = when
    }
    if (next === null) break
    time = next
  }

  return { runs, makespan }
}

/** The index in the pool of the task to start now, or -1 when there is none. */
function pickReady(pool, readyAt, priority, time) {
  let best = -1
  for (let i = 0; i < pool.length; i += 1) {
    const name = pool[i]
    if (readyAt.get(name) > time) continue
    if (best === -1) {
      best = i
      continue
    }
    const current = pool[best]
    const better =
      priority.get(name) > priority.get(current) ||
      (priority.get(name) === priority.get(current) && compareNames(name, current) < 0)
    if (better) best = i
  }
  return best
}
"}

