{"file_path":".scratch/ref.mjs","content":"// Naive literal reference for pack, used only to cross-check src/schedule.js.
import { readFileSync } from 'node:fs'

const text = readFileSync(0, 'utf8')
const workers = Number(process.argv[2])
const tasks = new Map()
const edges = []
for (const raw of text.split('\n')) {
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) continue
  const w = line.split(/\s+/)
  if (w[0] === 'task') tasks.set(w[1], { name: w[1], cost: Number(w[2]), deps: [] })
  else edges.push(w.slice(1))
}
for (const e of edges) {
  const t = tasks.get(e[0])
  for (const d of e.slice(1)) if (!t.deps.includes(d)) t.deps.push(d)
}
