  switch (node.kind) {
    case 'reference': {
      const address = parseAddress(node.text)
      if (address !== null) found.set(address.key, address)
      break
    }
    case 'range': {
      const from = parseAddress(node.from)
      const to = parseAddress(node.to)
      if (from === null || to === null) break
      for (let col = Math.min(from.col, to.col); col <= Math.max(from.col, to.col); col += 1) {
        for (let row = Math.min(from.row, to.row); row <= Math.max(from.row, to.row); row += 1) {
          found.set(formatAddress(col, row), { col, row })
        }
      }
      break
    }
    case 'group':
      collect(node.inner, found)
      break
    case 'unary':
      collect(node.operand, found)
      break
    case 'binary':
      collect(node.left, found)
      collect(node.right, found)
      break
    case 'call':
      for (const arg of node.args) collect(arg, found)
      break
    default:
      break
  }
}

export { error }
"}

