const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCT = [
  '==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.',
]

const TAB_WIDTH = 4

function isDigit(ch) {
  return ch >= '0' && ch <= '9'
}

function isHex(ch) {
  return ch !== undefined && /^[0-9a-fA-F]$/.test(ch)
}

function isLetter(ch) {
  return ch !== undefined && ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z'))
}

function isIdentStart(ch) {
  return ch === '_' || isLetter(ch)
}

function isIdentPart(ch) {
  return isIdentStart(ch) || (ch !== undefined && isDigit(ch))
}

function digitOfRadix(ch, radix) {
  if (ch === undefined) return false
  if (radix === 16) return isHex(ch)
  if (radix === 8) return ch >= '0' && ch <= '7'
  if (radix === 2) return ch === '0' || ch === '1'
  return isDigit(ch)
}

class Scanner {
  constructor(source) {
    this.chars = Array.from(source)
    this.i = 0
    this.line = 1
    this.column = 1
  }

  peek(offset = 0) {
    return this.chars[this.i + offset]
  }

  atEnd() {
    return this.i >= this.chars.length
  }

  /** Reads one code point, keeping the line and column in step with it. */
  next() {
    const ch = this.chars[this.i]
    this.i += 1
    if (ch === '\n') {
      this.line += 1
      this.column = 1
    } else if (ch === '\t') {
      this.column += TAB_WIDTH - ((this.column - 1) % TAB_WIDTH)
    } else {
      this.column += 1
    }
    return ch
  }

  fail(line, column, reason) {
    throw new ScanError(line, column, reason)
  }

  scan() {
    const tokens = []
    for (;;) {
      this.skipTrivia()
      if (this.atEnd()) return tokens
      tokens.push(this.token())
    }
  }

  skipTrivia() {
    for (;;) {
      const ch = this.peek()
      if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') {
        this.next()
        continue
      }
      if (ch === '/' && this.peek(1) === '/') {
        while (!this.atEnd() && this.peek() !== '\n') this.next()
        continue
      }
      if (ch === '/' && this.peek(1) === '*') {
        this.blockComment()
        continue
      }
      return
    }
  }

  blockComment() {
    const line = this.line
    const column = this.column
    let depth = 0
    for (;;) {
      if (this.atEnd()) this.fail(line, column, 'unterminated block comment')
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.next()
        this.next()
        depth += 1
        continue
      }
      if (this.peek() === '*' && this.peek(1) === '/') {
        this.next()
        this.next()
        depth -= 1
        if (depth === 0) return
        continue
      }
      this.next()
    }
  }

  token() {
    const line = this.line
    const column = this.column
    const ch = this.peek()

    if (ch === 'r' && this.peek(1) === '"') return this.rawString(line, column)
    if (isIdentStart(ch)) return this.identifier(line, column)
    if (isDigit(ch)) return this.number(line, column)
    if (ch === '"') return this.string(line, column)

    for (const op of PUNCT) {
      if (op.length === 2 && this.peek() === op[0] && this.peek(1) === op[1]) {
        this.next()
        this.next()
        return { line, column, kind: 'punct', text: op }
      }
    }
    for (const op of PUNCT) {
      if (op.length === 1 && ch === op) {
        this.next()
        return { line, column, kind: 'punct', text: op }
      }
    }
    this.fail(line, column, `unexpected character ${ch}`)
  }

  identifier(line, column) {
    let text = ''
    while (isIdentPart(this.peek())) text += this.next()
    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    return { line, column, kind, text }
  }

  /** Consumes the run of identifier characters that made a number invalid. */
  numberError(line, column, text) {
    let full = text
    while (isIdentPart(this.peek())) full += this.next()
    this.fail(line, column, `invalid number ${full}`)
  }

  /**
   * Reads digits of `radix`, allowing a single `_` between two of them.
   * Returns the text read and how many digits it held.
   */
  digitRun(radix) {
    let text = ''
    let digits = 0
    for (;;) {
      const ch = this.peek()
      if (digitOfRadix(ch, radix)) {
        text += this.next()
        digits += 1
        continue
      }
      if (ch === '_' && digits > 0 && digitOfRadix(this.peek(1), radix)) {
        text += this.next()
        continue
      }
      return { text, digits }
    }
  }

  number(line, column) {
    let text = ''
    if (this.peek() === '0' && 'xXbBoO'.includes(this.peek(1))) {
      text += this.next()
      const marker = this.next()
      text += marker
      const radix = 'xX'.includes(marker) ? 16 : 'bB'.includes(marker) ? 2 : 8
      const run = this.digitRun(radix)
      text += run.text
      if (run.digits === 0) this.numberError(line, column, text)
      if (isIdentPart(this.peek())) this.numberError(line, column, text)
      return { line, column, kind: 'number', text }
    }

    text += this.digitRun(10).text
    if (this.peek() === '.' && isDigit(this.peek(1))) {
      text += this.next()
      text += this.digitRun(10).text
    }
    const marker = this.peek()
    if (marker === 'e' || marker === 'E') {
      const after = this.peek(1)
      const signed = after === '+' || after === '-'
      if (isDigit(after) || (signed && isDigit(this.peek(2)))) {
        text += this.next()
        if (signed) text += this.next()
        text += this.digitRun(10).text
      }
    }
    if (isIdentPart(this.peek())) this.numberError(line, column, text)
    return { line, column, kind: 'number', text }
  }

  rawString(line, column) {
    this.next()
    this.next()
    let value = ''
    for (;;) {
      if (this.atEnd()) this.fail(line, column, 'unterminated string')
      const ch = this.next()
      if (ch === '"') return { line, column, kind: 'rawstring', text: value }
      value += ch
    }
  }

  string(line, column) {
    this.next()
    let value = ''
    for (;;) {
      if (this.atEnd()) this.fail(line, column, 'unterminated string')
      if (this.peek() === '\n') this.fail(this.line, this.column, 'newline in string')
      if (this.peek() === '"') {
        this.next()
        return { line, column, kind: 'string', text: value }
      }
      if (this.peek() === '\\') {
        value += this.escape(line, column)
        continue
      }
      value += this.next()
    }
  }

  escape(stringLine, stringColumn) {
    const line = this.line
    const column = this.column
    this.next()
    if (this.atEnd()) this.fail(stringLine, stringColumn, 'unterminated string')
    const ch = this.next()
    const bad = () => this.fail(line, column, `invalid escape \\${ch}`)
    switch (ch) {
      case 'n': return '\n'
      case 't': return '\t'
      case 'r': return '\r'
      case '\\': return '\\'
      case '"': return '"'
      case '0': return '\0'
      case 'x': {
        const a = this.peek()
        const b = this.peek(1)
        if (!isHex(a) || !isHex(b)) bad()
        this.next()
        this.next()
        return String.fromCharCode(parseInt(a + b, 16))
      }
      case 'u': {
        if (this.peek() !== '{') bad()
        let digits = ''
        let offset = 1
        while (isHex(this.peek(offset))) {
          digits += this.peek(offset)
          offset += 1
        }
        if (digits.length === 0 || this.peek(offset) !== '}') bad()
        const value = parseInt(digits, 16)
        if (!(value <= 0x10ffff)) bad()
        for (let k = 0; k <= offset; k += 1) this.next()
        return String.fromCodePoint(value)
      }
      default:
        return bad()
    }
  }
}

export function scan(source) {
  return new Scanner(source).scan()
}

export const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']
"}

