{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { readFileSync } from 'node:fs'
import { scan, ScanError, KINDS } from './lexer.js'

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function body(token) {
  if (token.kind === 'string' || token.kind === 'rawstring') return JSON.stringify(token.text)
  return token.text
}

function main(argv) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'tokens' && mode !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    return 2
  }

  let tokens
  try {
    tokens = scan(readStdin())
  } catch (error) {
    if (!(error instanceof ScanError)) throw error
    process.stderr.write(`error: ${error.line}:${error.column}: ${error.reason}\n`)
    return 2
  }

  let out = ''
  if (mode === 'tokens') {
    for (const token of tokens) out += `${token.line}:${token.column} ${token.kind} ${body(token)}\n`
  } else {
    for (const kind of KINDS) out += `${kind} ${tokens.filter((t) => t.kind === kind).length}\n`
    out += `total ${tokens.length}\n`
  }
  process.stdout.write(out)
  return 0
}

process.exitCode = main(process.argv.slice(2))
"}

