{"file_path":"src/format.js","content":"/**
 * The two ways of printing a parsed document: canonical JSON and the flat
 * listing of paths with their types.
 */

import { sortedKeys } from './values.js'

function renderNumber(node) {
  if (node.type === 'integer') return String(node.value)
  return JSON.stringify(node.value)
}

function render(node, indent) {
  const pad = '  '.repeat(indent)
  const inner = '  '.repeat(indent + 1)
  if (node.type === 'table') {
    const keys = sortedKeys(node)
    if (keys.length === 0) return '{}'
    const parts = keys.map((key) => `${inner}${JSON.stringify(key)}: ${render(node.props.get(key), indent + 1)}`)
    return `{\n${parts.join(',\n')}\n${pad}}`
  }
  if (node.type === 'array') {
    if (node.items.length === 0) return '[]'
    const parts = node.items.map((item) => `${inner}${render(item, indent + 1)}`)
    return `[\n${parts.join(',\n')}\n${pad}]`
  }
  if (node.type === 'string') return JSON.stringify(node.value)
  if (node.type === 'boolean') return node.value ? 'true' : 'false'
  return renderNumber(node)
}

/** The document as JSON indented by two spaces, with a trailing newline. */
export function toJson(root) {
  return `${render(root, 0)}\n`
}

function walkKeys(node, path, out) {
  if (node.type === 'table') {
    for (const key of sortedKeys(node)) {
      const child = node.props.get(key)
      const childPath = path === '' ? key : `${path}.${key}`
      out.push(`${childPath} ${child.type}`)
      walkKeys(child, childPath, out)
    }
    return
  }
  if (node.type === 'array') {
    node.items.forEach((item, index) => {
      const childPath = `${path}[${index}]`
      out.push(`${childPath} ${item.type}`)
      walkKeys(item, childPath, out)
    })
  }
}

/** One line per node below the root, each before its children. */
export function toKeys(root) {
  const out = []
  walkKeys(root, '', out)
  return out.map((line) => `${line}\n`).join('')
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { readFileSync } from 'node:fs'
import { parseDocument } from './parse.js'
import { toJson, toKeys } from './format.js'
import { ConfError } from './values.js'

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main(argv) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'json' && mode !== 'keys')) {
    process.stderr.write('error: usage: cli.js json|keys\n')
    process.exit(2)
  }
  let output
  try {
    const root = parseDocument(readStdin())
    output = mode === 'json' ? toJson(root) : toKeys(root)
  } catch (err) {
    if (err instanceof ConfError) {
      process.stderr.write(`error: line ${err.line}: ${err.reason}\n`)
      process.exit(2)
    }
    throw err
  }
  process.stdout.write(output)
}

main(process.argv.slice(2))
"}

