{"file_path":"src/uri.js","content":"/**
 * RFC 3986 URI reference parsing, normalization and reference resolution.
 */

export class UriError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

const HEX = /^[0-9A-Fa-f]{2}$/

function asciiLower(s) {
  return s.replace(/[A-Z]/g, (c) => String.fromCharCode(c.charCodeAt(0) + 32))
}

function isUnreserved(code) {
  return (
    (code >= 0x41 && code <= 0x5a) ||
    (code >= 0x61 && code <= 0x7a) ||
    (code >= 0x30 && code <= 0x39) ||
    code === 0x2d /* - */ ||
    code === 0x2e /* . */ ||
    code === 0x5f /* _ */ ||
    code === 0x7e /* ~ */
  )
}

/** Parse a URI reference into its five generic-syntax components. */
export function parse(ref) {
  let rest = ref
  let scheme
  const schemeEnd = rest.indexOf(':')
  if (schemeEnd >= 0) {
    const head = rest.slice(0, schemeEnd)
    if (!/[/?#]/.test(head)) {
      scheme = head
      rest = rest.slice(schemeEnd + 1)
    }
  }
  let authority
  if (rest.startsWith('//')) {
    rest = rest.slice(2)
    const m = rest.search(/[/?#]/)
    if (m < 0) {
      authority = rest
      rest = ''
    } else {
      authority = rest.slice(0, m)
      rest = rest.slice(m)
    }
  }
  let fragment
  const hash = rest.indexOf('#')
  if (hash >= 0) {
    fragment = rest.slice(hash + 1)
    rest = rest.slice(0, hash)
  }
  let query
  const q = rest.indexOf('?')
  if (q >= 0) {
    query = rest.slice(q + 1)
    rest = rest.slice(0, q)
  }
  return { scheme, authority, path: rest, query, fragment }
}

/** Split an authority into userinfo, host and port. */
export function splitAuthority(authority) {
  if (authority === undefined) return { userinfo: undefined, host: undefined, port: undefined }
  let userinfo
  let rest = authority
  const at = rest.lastIndexOf('@')
  if (at >= 0) {
    userinfo = rest.slice(0, at)
    rest = rest.slice(at + 1)
  }
  let host = rest
  let port
  const bracket = rest.lastIndexOf(']')
  const colon = rest.indexOf(':', bracket + 1)
  if (colon >= 0) {
    host = rest.slice(0, colon)
    port = rest.slice(colon + 1)
  }
  return { userinfo, host, port }
}

function joinAuthority({ userinfo, host, port }) {
  let a = ''
  if (userinfo !== undefined) a += userinfo + '@'
  a += host
  if (port !== undefined) a += ':' + port
  return a
}

function checkPercent(s, component) {
  if (s === undefined) return
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '%') {
      if (!HEX.test(s.slice(i + 1, i + 3))) throw new UriError(component)
      i += 2
    }
  }
}

/** Validate the percent-encodings of every component, in the specified order. */
export function checkComponents(uri) {
  const { userinfo, host } = splitAuthority(uri.authority)
  checkPercent(uri.path, 'path')
  checkPercent(userinfo, 'userinfo')
  checkPercent(host, 'host')
  checkPercent(uri.query, 'query')
  checkPercent(uri.fragment, 'fragment')
}

function normalizePercent(s, component) {
  if (s === undefined) return undefined
  let out = ''
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '%') {
      const hex = s.slice(i + 1, i + 3)
      if (!HEX.test(hex)) throw new UriError(component)
      const code = parseInt(hex, 16)
      if (isUnreserved(code)) out += String.fromCharCode(code)
      else out += '%' + hex.toUpperCase()
      i += 2
    } else {
      out += s[i]
    }
  }
  return out
}

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

