export function format(uri) {
  let s = ''
  if (uri.scheme !== undefined) s += uri.scheme + ':'
  if (uri.authority !== undefined) s += '//' + uri.authority
  s += uri.path
  if (uri.query !== undefined) s += '?' + uri.query
  if (uri.fragment !== undefined) s += '#' + uri.fragment
  return s
}

