  if (base.authority !== undefined && base.path === '') return '/' + refPath
  const cut = base.path.lastIndexOf('/')
  if (cut < 0) return refPath
  return base.path.slice(0, cut + 1) + refPath
}

/** Resolve a reference against a base, per RFC 3986 section 5.2.2 (strict). */
export function resolve(base, ref) {
  let target
  if (ref.scheme !== undefined) {
    target = {
      scheme: ref.scheme,
