{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { parse, normalize, format, resolve, checkComponents, UriError } from './uri.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const argv = process.argv.slice(2)
const mode = argv[0]
if (argv.length !== 1 || (mode !== 'normalize' && mode !== 'resolve')) {
  fail('usage: cli.js normalize|resolve')
}

let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch {
  input = ''
}

const lines = input.split('\n')
if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

const out = []
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const record = lines[i]
  try {
    if (mode === 'normalize') {
      const ref = parse(record)
      checkComponents(ref)
      out.push(format(normalize(ref)))
    } else {
      const space = record.indexOf(' ')
      if (space < 0) fail(`line ${n}: expected a base and a reference`)
      const base = parse(record.slice(0, space))
      const ref = parse(record.slice(space + 1))
      if (base.scheme === undefined) fail(`line ${n}: the base has no scheme`)
      checkComponents(base)
      checkComponents(ref)
      out.push(format(normalize(resolve(base, ref))))
    }
  } catch (error) {
    if (error instanceof UriError) fail(`line ${n}: ${error.message}`)
    throw error
  }
}

process.stdout.write(out.map((line) => line + '\n').join(''))
"}

