{"file_path":"src/diff.js","content":"/**
 * Longest common subsequence over whole lines, with the earliest-match
 * tie-breaking rule the specification asks for, and the change runs it leaves.
 */

/**
 * Table of LCS lengths: lengths[i][j] is the length of the longest common
 * subsequence of a.slice(i) and b.slice(j).
 */
function lcsLengths(a, b) {
  const n = a.length
  const m = b.length
  const table = new Array(n + 1)
  for (let i = 0; i <= n; i += 1) table[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i -= 1) {
    for (let j = m - 1; j >= 0; j -= 1) {
      if (a[i] === b[j]) table[i][j] = table[i + 1][j + 1] + 1
      else table[i][j] = Math.max(table[i + 1][j], table[i][j + 1])
    }
  }
  return table
}

/**
 * The matched pairs of a longest common subsequence of base and side, taking
 * matches as early as possible and preferring to advance the base on a tie.
 */
export function matches(base, side) {
  const table = lcsLengths(base, side)
  const pairs = []
  let i = 0
  let j = 0
  while (i < base.length && j < side.length) {
    if (base[i] === side[j]) {
      pairs.push([i, j])
      i += 1
      j += 1
    } else if (table[i + 1][j] >= table[i][j + 1]) {
      i += 1
    } else {
      j += 1
    }
  }
  return pairs
}

/**
 * The stretches the common subsequence does not cover, each a run of base lines
 * replaced by a run of the side's lines.
 */
export function changes(base, side) {
  const pairs = matches(base, side)
  const result = []
  let baseAt = 0
  let sideAt = 0
  const flush = (baseEnd, sideEnd) => {
    if (baseEnd > baseAt || sideEnd > sideAt) {
      result.push({ baseStart: baseAt, baseEnd, sideStart: sideAt, sideEnd })
    }
  }
  for (const [i, j] of pairs) {
    flush(i, j)
    baseAt = i + 1
    sideAt = j + 1
  }
  flush(base.length, side.length)
  return result
}
"}

