{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { regionsOf, mergeLines, regionLines } from './merge.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** Everything standard input holds, as text. */
function readStdin() {
  const chunks = []
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

/** The three documents the input holds, or null when it holds another count. */
export function parseInput(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') parts.push([])
    else parts[parts.length - 1].push(line)
  }
  return parts.length === 3 ? parts : null
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || !MODES.has(argv[0])) fail('usage: cli.js merge|merge2|regions')
  const mode = argv[0]

  let text = ''
  try {
    text = readStdin()
  } catch {
    text = ''
  }
  const parts = parseInput(text)
  if (parts === null) fail('expected three parts separated by %%%')

  const [mine, base, theirs] = parts
  const regions = regionsOf(mine, base, theirs)
  const result = mode === 'regions' ? regionLines(regions) : mergeLines(regions, mode === 'merge')
  const out = result.lines.map(line => `${line}\n`).join('')
  process.stdout.write(out)
  process.exit(result.conflicted ? 1 : 0)
}

main()
"}

