{"file_path":"src/format.js","content":"/** Rendering of a finished count. */

function byVotesThenName(counts) {
  return [...counts.keys()].sort((a, b) => {
    const diff = counts.get(b) - counts.get(a)
    if (diff !== 0) return diff
    return a < b ? -1 : a > b ? 1 : 0
  })
}

export function formatRounds(result) {
  const out = []
  result.rounds.forEach((round, index) => {
    const parts = byVotesThenName(round.counts).map((name) => `${name}=${round.counts.get(name)}`)
    parts.push(`exhausted=${round.exhausted}`)
    out.push(`round ${index + 1}: ${parts.join(' ')}`)
    if (round.eliminated !== null) out.push(`eliminated ${round.eliminated}`)
  })
  out.push(outcome(result))
  return out.map((line) => `${line}\n`).join('')
}

export function formatTally(result) {
  return `rounds ${result.rounds.length}\n${outcome(result)}\n`
}

function outcome(result) {
  return result.winner === null ? 'no winner' : `winner ${result.winner}`
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'
import { ParseError, parseElection } from './parse.js'
import { runElection } from './count.js'
import { formatRounds, formatTally } from './format.js'

function die(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main(argv) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'rounds' && mode !== 'tally')) {
    die('usage: cli.js rounds|tally')
  }

  let election
  try {
    election = parseElection(readStdin())
  } catch (error) {
    if (error instanceof ParseError) die(error.message)
    throw error
  }

  const result = runElection(election.candidates, election.ballots)
  process.stdout.write(mode === 'rounds' ? formatRounds(result) : formatTally(result))
}

main(process.argv.slice(2))
"}

