{"file_path":"src/uri.js","content":"/**
 * URI parsing, normalization and reference resolution following RFC 3986.
 */

export class UriError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

const DEFAULT_PORTS = {
  http: '80',
  ws: '80',
  https: '443',
  wss: '443',
  ftp: '21',
}

const HEX = '0123456789abcdefABCDEF'

function isHex(ch) {
  return ch !== undefined && HEX.includes(ch)
}

function asciiLower(text) {
  let out = ''
  for (const ch of text) {
    const code = ch.codePointAt(0)
    out += code >= 0x41 && code <= 0x5a ? String.fromCharCode(code + 32) : ch
  }
  return out
}

function isUnreserved(code) {
  return (
    (code >= 0x41 && code <= 0x5a) ||
    (code >= 0x61 && code <= 0x7a) ||
    (code >= 0x30 && code <= 0x39) ||
    code === 0x2d /* - */ ||
    code === 0x2e /* . */ ||
    code === 0x5f /* _ */ ||
    code === 0x7e /* ~ */
  )
}

/** Parse a URI reference into its five generic-syntax components. */
export function parse(text) {
  let rest = text
  let scheme
  for (let i = 0; i < rest.length; i += 1) {
    const ch = rest[i]
    if (ch === '/' || ch === '?' || ch === '#') break
    if (ch === ':') {
      scheme = rest.slice(0, i)
      rest = rest.slice(i + 1)
      break
    }
  }

  let authority
  if (rest.startsWith('//')) {
    rest = rest.slice(2)
    let end = rest.length
    for (let i = 0; i < rest.length; i += 1) {
      const ch = rest[i]
      if (ch === '/' || ch === '?' || ch === '#') {
        end = i
        break
      }
    }
    authority = rest.slice(0, end)
    rest = rest.slice(end)
  }

  let fragment
  const hash = rest.indexOf('#')
  if (hash >= 0) {
    fragment = rest.slice(hash + 1)
    rest = rest.slice(0, hash)
  }

  let query
  const mark = rest.indexOf('?')
  if (mark >= 0) {
    query = rest.slice(mark + 1)
    rest = rest.slice(0, mark)
  }

  const uri = { scheme, authority, path: rest, query, fragment }
  Object.assign(uri, splitAuthority(authority))
  return uri
}

function splitAuthority(authority) {
  if (authority === undefined) return { userinfo: undefined, host: undefined, port: undefined }
  let userinfo
  let rest = authority
  const at = rest.lastIndexOf('@')
  if (at >= 0) {
    userinfo = rest.slice(0, at)
    rest = rest.slice(at + 1)
  }
  let port
  let host = rest
  const bracket = rest.lastIndexOf(']')
  const colon = rest.indexOf(':', bracket + 1)
  if (colon >= 0) {
    port = rest.slice(colon + 1)
    host = rest.slice(0, colon)
  }
  return { userinfo, host, port }
}

function joinAuthority(uri) {
  if (uri.authority === undefined) return undefined
  let out = ''
  if (uri.userinfo !== undefined) out += `${uri.userinfo}@`
  out += uri.host ?? ''
  if (uri.port !== undefined) out += `:${uri.port}`
  return out
}

/** Check that every percent sign in `text` starts a complete triplet. */
export function checkPercent(text, component) {
  if (text === undefined) return
  for (let i = 0; i < text.length; i += 1) {
    if (text[i] !== '%') continue
    if (!isHex(text[i + 1]) || !isHex(text[i + 2])) throw new UriError(component)
  }
}

/** Validate the percent-encodings of a parsed reference, component by component. */
export function checkUri(uri) {
  checkPercent(uri.path, 'path')
  checkPercent(uri.userinfo, 'userinfo')
  checkPercent(uri.host, 'host')
  checkPercent(uri.query, 'query')
  checkPercent(uri.fragment, 'fragment')
}

function normalizePercent(text, component) {
  if (text === undefined) return undefined
  let out = ''
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i]
    if (ch !== '%') {
      out += ch
      continue
    }
    const a = text[i + 1]
    const b = text[i + 2]
    if (!isHex(a) || !isHex(b)) throw new UriError(component)
    const triplet = `%${a.toUpperCase()}${b.toUpperCase()}`
    const code = parseInt(a + b, 16)
    out += isUnreserved(code) ? String.fromCharCode(code) : triplet
    i += 2
  }
  return out
}

/** RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = `/${input.slice(3)}`
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = `/${input.slice(4)}`
      output = output.slice(0, Math.max(0, output.lastIndexOf('/')))
    } else if (input === '/..') {
      input = '/'
      output = output.slice(0, Math.max(0, output.lastIndexOf('/')))
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let end = input.startsWith('/') ? input.indexOf('/', 1) : input.indexOf('/')
      if (end < 0) end = input.length
      output += input.slice(0, end)
      input = input.slice(end)
    }
  }
  return output
}

/** Normalize a parsed reference and return its string form. */
export function normalize(uri) {
  const out = { ...uri }
  if (out.scheme !== undefined) out.scheme = asciiLower(out.scheme)

  out.path = normalizePercent(out.path, 'path')
  out.userinfo = normalizePercent(out.userinfo, 'userinfo')
  out.host = normalizePercent(out.host, 'host')
  out.query = normalizePercent(out.query, 'query')
  out.fragment = normalizePercent(out.fragment, 'fragment')

  if (out.host !== undefined) out.host = asciiLower(out.host)

  if (out.port !== undefined) {
    const fallback = out.scheme === undefined ? undefined : DEFAULT_PORTS[out.scheme]
    if (out.port === '' || (fallback !== undefined && out.port === fallback)) out.port = undefined
  }

  out.path = removeDotSegments(out.path)
  if (out.authority !== undefined && out.path === '') out.path = '/'

  out.authority = joinAuthority(out)
  return format(out)
}

/** Render a parsed reference back to text. */
export function format(uri) {
  let out = ''
  if (uri.scheme !== undefined) out += `${uri.scheme}:`
  if (uri.authority !== undefined) out += `//${uri.authority}`
  out += uri.path
  if (uri.query !== undefined) out += `?${uri.query}`
  if (uri.fragment !== undefined) out += `#${uri.fragment}`
  return out
}

function merge(base, refPath) {
  if (base.authority !== undefined && base.path === '') return `/${refPath}`
  const slash = base.path.lastIndexOf('/')
  if (slash < 0) return refPath
  return base.path.slice(0, slash + 1) + refPath
}

/** RFC 3986 section 5.2.2, strict. Returns a parsed target reference. */
export function resolve(base, ref) {
  let target
  if (ref.scheme !== undefined) {
    target = {
      scheme: ref.scheme,
      authority: ref.authority,
      path: removeDotSegments(ref.path),
      query: ref.query,
    }
    Object.assign(target, splitAuthority(target.authority))
  } else if (ref.authority !== undefined) {
    target = {
      scheme: base.scheme,
      authority: ref.authority,
      path: removeDotSegments(ref.path),
      query: ref.query,
    }
    Object.assign(target, splitAuthority(target.authority))
  } else {
    let path
    let query
    if (ref.path === '') {
      path = base.path
      query = ref.query !== undefined ? ref.query : base.query
    } else {
      path = ref.path.startsWith('/')
        ? removeDotSegments(ref.path)
        : removeDotSegments(merge(base, ref.path))
      query = ref.query
    }
    target = { scheme: base.scheme, authority: base.authority, path, query }
    Object.assign(target, splitAuthority(target.authority))
  }
  target.fragment = ref.fragment
  return target
}
"}

