{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'node:fs'
import { regionsOf, resolve } from './merge.js'

const MODES = ['merge', 'merge2', 'regions']

/** The three documents the input holds, or null when it does not hold three. */
export function parse(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') parts.push([])
    else parts[parts.length - 1].push(line)
  }
  return parts.length === 3 ? parts : null
}

/** The output of one mode, and whether any conflict was written. */
export function render(mode, [mine, base, theirs]) {
  const out = []
  let conflicted = false
  for (const region of regionsOf(mine, base, theirs)) {
    if (region.kind === 'stable') {
      if (mode === 'regions') out.push(`stable ${region.lines.length}`)
      else out.push(...region.lines)
      continue
    }
    const resolution = resolve(region)
    if (resolution.kind !== 'conflict') {
      if (mode === 'regions') out.push(`${resolution.kind} ${resolution.lines.length}`)
      else out.push(...resolution.lines)
      continue
    }
    conflicted = true
    if (mode === 'regions') {
      out.push(`conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}`)
      continue
    }
    out.push('<<<<<<< mine', ...region.mine)
    if (mode === 'merge') out.push('||||||| base', ...region.base)
    out.push('=======', ...region.theirs, '>>>>>>> theirs')
  }
  return { text: out.map(line => `${line}\n`).join(''), conflicted }
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main(argv) {
  if (argv.length !== 1 || !MODES.includes(argv[0])) fail('usage: cli.js merge|merge2|regions')
  const parts = parse(readFileSync(0, 'utf8'))
  if (parts === null) fail('expected three parts separated by %%%')
  const { text, conflicted } = render(argv[0], parts)
  process.stdout.write(text)
  process.exitCode = conflicted ? 1 : 0
}

main(process.argv.slice(2))
"}

