{"file_path":"src/limiter.js","content":"/**
 * Parsing and simulation of limiter files.
 */

const TOKEN_RE = /^[A-Za-z0-9_./:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

function isToken(word) {
  return TOKEN_RE.test(word)
}

function integerAtLeast(word, field, least, lineNo) {
  if (!INT_RE.test(word)) throw new ParseError(lineNo, `${field} must be an integer of at least ${least}`)
  const value = BigInt(word)
  if (value < least) throw new ParseError(lineNo, `${field} must be an integer of at least ${least}`)
  return value
}

class Bucket {
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity
    this.refill = refill
    this.per = per
    // tokens are stored as a numerator over `per`, so fractions stay exact
    this.cap = capacity * per
    this.states = new Map()
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { num: this.cap, last: tick }
      this.states.set(key, state)
      return
    }
    const elapsed = tick - state.last
    if (elapsed > 0n) {
      state.num += this.refill * elapsed
      if (state.num > this.cap) state.num = this.cap
      state.last = tick
    }
  }

  allows(key) {
    return this.states.get(key).num >= this.per
  }

  record(key) {
    const state = this.states.get(key)
    state.num -= this.per
  }
}

class Window {
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  advance(key, tick) {
    let ticks = this.states.get(key)
    if (ticks === undefined) {
      ticks = []
