{"file_path":"src/diff.js","content":"/**
 * Longest common subsequence over whole lines, with the tie-breaking the
 * specification asks for, and the changes it leaves uncovered.
 */

/**
 * The matched pairs of indices of a longest common subsequence of `base` and
 * `side`. Ties are broken so that the matches come as early as possible:
 * whenever the two current lines differ, the side whose remaining subsequence
 * is at least as long as the other's advances, the base first when they tie.
 */
export function lcsMatches(base, side) {
  const n = base.length
  const m = side.length
  // table[i][j] is the length of the longest common subsequence of the
  // suffixes base[i..] and side[j..].
  const table = []
  for (let i = 0; i <= n; i += 1) table.push(new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i -= 1) {
    const row = table[i]
    const next = table[i + 1]
    for (let j = m - 1; j >= 0; j -= 1) {
      row[j] = base[i] === side[j] ? next[j + 1] + 1 : Math.max(next[j], row[j + 1])
    }
  }
  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i += 1
      j += 1
    } else if (table[i + 1][j] >= table[i][j + 1]) {
      i += 1
    } else {
      j += 1
    }
  }
  return matches
}

/**
 * The stretches the common subsequence does not cover, each a run of base
 * lines replaced by a run of the side's lines.
 */
export function changes(base, side) {
  const result = []
  let baseAt = 0
  let sideAt = 0
  const push = (baseEnd, lineEnd) => {
    if (baseEnd > baseAt || lineEnd > sideAt) {
      result.push({ baseStart: baseAt, baseEnd, lineStart: sideAt, lineEnd })
    }
  }
  for (const [i, j] of lcsMatches(base, side)) {
    push(i, j)
    baseAt = i + 1
    sideAt = j + 1
  }
  push(base.length, side.length)
  return result
}
"}

