import { changes } from './diff.js'

const equal = (a, b) => a.length === b.length && a.every((line, index) => line === b[index])

/**
 * The regions of the merge, in base order. A stable region is
 * `{ kind: 'stable', lines }`; a changed one carries the three candidate runs
 * and its resolution.
 */
export function regions(mine, base, theirs) {
  const marked = [
    ...changes(base, mine).map(change => ({ ...change, side: 'mine' })),
    ...changes(base, theirs).map(change => ({ ...change, side: 'theirs' })),
  ]
  // Ordered by where they start in the base, mine first at the same place.
  marked.sort((a, b) => a.baseStart - b.baseStart || (a.side === b.side ? 0 : a.side === 'mine' ? -1 : 1))

  const groups = []
  let at = 0
  while (at < marked.length) {
    const group = [marked[at]]
    let end = marked[at].baseEnd
    at += 1
    while (at < marked.length && marked[at].baseStart <= end) {
      end = Math.max(end, marked[at].baseEnd)
      group.push(marked[at])
      at += 1
    }
    groups.push({ start: group[0].baseStart, end, group })
  }

  const documents = { mine, theirs }
  const result = []
  let baseAt = 0
  for (const { start, end, group } of groups) {
    if (start > baseAt) result.push({ kind: 'stable', lines: base.slice(baseAt, start) })
    baseAt = end
    result.push(resolve(group, start, end, base, documents))
  }
  if (base.length > baseAt) result.push({ kind: 'stable', lines: base.slice(baseAt) })
  return result
}

function sideLines(group, side, start, end, base, documents) {
  const own = group.filter(change => change.side === side)
  if (own.length === 0) return base.slice(start, end)
  let minStart = Infinity
  let maxEnd = -Infinity
  let lineStart = 0
  let lineEnd = 0
  for (const change of own) {
    if (change.baseStart < minStart) {
      minStart = change.baseStart
      lineStart = change.lineStart
    }
    if (change.baseEnd > maxEnd) {
      maxEnd = change.baseEnd
      lineEnd = change.lineEnd
    }
  }
  return documents[side].slice(lineStart - (minStart - start), lineEnd + (end - maxEnd))
}

function resolve(group, start, end, base, documents) {
  const mine = sideLines(group, 'mine', start, end, base, documents)
  const theirs = sideLines(group, 'theirs', start, end, base, documents)
  const middle = base.slice(start, end)
  const region = { mine, base: middle, theirs }
  if (equal(mine, theirs)) return { ...region, kind: 'both', lines: mine }
  if (equal(mine, middle)) return { ...region, kind: 'theirs', lines: theirs }
  if (equal(theirs, middle)) return { ...region, kind: 'mine', lines: mine }
  return { ...region, kind: 'conflict' }
}
"}

