{"file_path":"src/parse.js","content":"/**
 * The limiter file parser. It turns the text of a limiter file into the
 * declarations, the routes and the event log of a program, or into the first
 * error the file contains.
 */

const TOKEN = /^[A-Za-z0-9_./:-]+$/
const INTEGER = /^(?:0|[1-9][0-9]*)$/

/** A parse failure carrying the line it was found on and its reason. */
export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

/** True when the word is a name, a route prefix or an event key. */
function isToken(word) {
  return TOKEN.test(word)
}

/**
 * The value of an unsigned decimal integer field, as a BigInt, or a failure
 * when it is not written plainly or is below the least value it allows.
 */
function integerField(line, field, word, least) {
  if (!INTEGER.test(word)) {
    throw new ParseError(line, `${field} must be an integer of at least ${least}`)
  }
  const value = BigInt(word)
  if (value < BigInt(least)) {
    throw new ParseError(line, `${field} must be an integer of at least ${least}`)
  }
  return value
}

/** The lines of the file, without the empty tail a trailing newline leaves. */
function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * The program the text describes: its policy declarations in the order they
 * were written, its routes, and its events.
 */
export function parseProgram(text) {
  const policies = []
  const byName = new Map()
  const routes = []
  const prefixes = new Set()
  const events = []
  let lastTick = null

  const lines = splitLines(text)
  for (let index = 0; index < lines.length; index += 1) {
    const number = index + 1
    const line = lines[index].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)
    const directive = words[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (events.length > 0) {
        throw new ParseError(number, 'declarations must come before the first event')
      }
    }

    if (directive === 'bucket') {
      if (words.length !== 5) {
        throw new ParseError(number, 'expected bucket <name> <capacity> <refill> <per>')
      }
      const name = words[1]
      if (!isToken(name)) throw new ParseError(number, `invalid policy name ${name}`)
      const capacity = integerField(number, 'capacity', words[2], 1)
      const refill = integerField(number, 'refill', words[3], 0)
      const per = integerField(number, 'per', words[4], 1)
      if (byName.has(name)) throw new ParseError(number, `policy ${name} is declared twice`)
      const policy = { kind: 'bucket', name, capacity, refill, per }
      byName.set(name, policy)
      policies.push(policy)
      continue
    }

    if (directive === 'window') {
      if (words.length !== 4) {
        throw new ParseError(number, 'expected window <name> <limit> <span>')
      }
      const name = words[1]
      if (!isToken(name)) throw new ParseError(number, `invalid policy name ${name}`)
      const limit = integerField(number, 'limit', words[2], 0)
      const span = integerField(number, 'span', words[3], 1)
      if (byName.has(name)) throw new ParseError(number, `policy ${name} is declared twice`)
      const policy = { kind: 'window', name, limit, span }
      byName.set(name, policy)
      policies.push(policy)
      continue
    }

    if (directive === 'route') {
      if (words.length < 3) {
        throw new ParseError(number, 'expected route <prefix> <policy>...')
      }
      const prefix = words[1]
      if (!isToken(prefix)) throw new ParseError(number, `invalid route prefix ${prefix}`)
      const named = []
      for (const word of words.slice(2)) {
        const policy = byName.get(word)
        if (policy === undefined) throw new ParseError(number, `unknown policy ${word}`)
        named.push(policy)
      }
      if (prefixes.has(prefix)) throw new ParseError(number, `prefix ${prefix} is routed twice`)
      prefixes.add(prefix)
      routes.push({ prefix, policies: named })
      continue
    }

    if (directive === 'event') {
      if (words.length !== 3) {
        throw new ParseError(number, 'expected event <tick> <key>')
      }
      const tick = integerField(number, 'tick', words[1], 0)
      const key = words[2]
      if (!isToken(key)) throw new ParseError(number, `invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) {
        throw new ParseError(number, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      events.push({ tick, key })
      continue
    }

    throw new ParseError(number, `unknown directive ${directive}`)
  }

  return { policies, routes, events }
}
"}

