{"file_path":"src/parse.js","content":"/**
 * Parsing of an election description into a candidate list and a ballot list.
 */

const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/

export class ParseError extends Error {}

function fail(message) {
  throw new ParseError(message)
}

/**
 * Split the raw input into significant lines, keeping each line's number.
 */
export function significantLines(text) {
  const raw = text.split('\n')
  if (raw.length > 0 && raw[raw.length - 1] === '') raw.pop()
  const lines = []
  for (let i = 0; i < raw.length; i += 1) {
    const line = raw[i].trim()
    if (line === '' || line.startsWith('#')) continue
    lines.push({ number: i + 1, words: line.split(/\s+/) })
  }
  return lines
}

/**
 * Parse an election, throwing a ParseError carrying the message to report.
 */
export function parseElection(text) {
  let candidates = null
  const declared = new Set()
  const ballots = []

  for (const { number, words } of significantLines(text)) {
    const directive = words[0]
    if (directive === 'candidates') {
      if (candidates !== null) {
        fail(`line ${number}: candidates must be declared once, before any ballot`)
      }
      const names = words.slice(1)
      if (names.length === 0) fail(`line ${number}: expected candidates <name>...`)
      for (const name of names) {
        if (!NAME.test(name)) fail(`line ${number}: invalid candidate name ${name}`)
        if (declared.has(name)) fail(`line ${number}: candidate ${name} is declared twice`)
        declared.add(name)
      }
      candidates = names
    } else if (directive === 'ballot') {
      if (candidates === null) {
        fail(`line ${number}: candidates must be declared once, before any ballot`)
      }
      if (words.length < 3) fail(`line ${number}: expected ballot <count> <candidate>...`)
      const count = words[1]
      if (!COUNT.test(count)) fail(`line ${number}: count must be a positive integer`)
      const ranking = words.slice(2)
      const seen = new Set()
      for (const name of ranking) {
        if (!declared.has(name)) fail(`line ${number}: unknown candidate ${name}`)
        if (seen.has(name)) fail(`line ${number}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: Number(count), ranking })
    } else {
      fail(`line ${number}: unknown directive ${directive}`)
    }
  }

  if (candidates === null) fail('no candidates')
  return { candidates, ballots }
}
"}

{"file_path":"src/count.js","content":"/**
 * The instant-runoff count.
 */

/**
 * Run the count, returning the rounds and the winner (or null).
 *
 * Each round is { counts: Map<name, votes>, exhausted, eliminated }.
 */
export function runElection({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const rounds = []
  let winner = null

  for (;;) {
    const counts = new Map()
    for (const name of candidates) {
      if (continuing.has(name)) counts.set(name, 0)
    }
    let exhausted = 0
    for (const ballot of ballots) {
      const choice = ballot.ranking.find((name) => continuing.has(name))
      if (choice === undefined) exhausted += ballot.count
      else counts.set(choice, counts.get(choice) + ballot.count)
    }
    let active = 0
    for (const votes of counts.values()) active += votes

    const round = { counts, exhausted, eliminated: null }
    rounds.push(round)

    if (active === 0) break

    let best = -1
    let leader = null
    for (const [name, votes] of counts) {
      if (votes > best) {
        best = votes
        leader = name
      }
    }
    if (best * 2 > active) {
      winner = leader
      break
    }

    const loser = pickLoser(rounds, [...counts.keys()])
    round.eliminated = loser
    continuing.delete(loser)
  }

  return { rounds, winner }
}

/**
 * Choose the candidate to eliminate among those tied for fewest votes now,
 * looking back over earlier rounds and finally at the names themselves.
 */
function pickLoser(rounds, names) {
  let pool = names
  let changed = true
  while (changed) {
    changed = false
    for (const round of rounds) {
      const votes = pool.map((name) => round.counts.get(name))
      const least = Math.min(...votes)
      const most = Math.max(...votes)
      if (least === most) continue
      pool = pool.filter((name) => round.counts.get(name) === least)
      changed = true
      break
    }
  }
  let loser = pool[0]
  for (const name of pool) {
    if (name > loser) loser = name
  }
  return loser
}
"}

