{"file_path":"src/format.js","content":"/**
 * Rendering of a finished count.
 */

function order(counts) {
  return [...counts.entries()].sort((a, b) => (b[1] - a[1]) || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
}

/**
 * The `rounds` report: every round, its eliminations, and the outcome.
 */
export function formatRounds({ rounds, winner }) {
  const lines = []
  rounds.forEach((round, index) => {
    const parts = order(round.counts).map(([name, votes]) => `${name}=${votes}`)
    parts.push(`exhausted=${round.exhausted}`)
    lines.push(`round ${index + 1}: ${parts.join(' ')}`)
    if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
  })
  lines.push(outcome(winner))
  return lines.map((line) => `${line}\n`).join('')
}

/**
 * The `tally` report: how many rounds ran, and the outcome.
 */
export function formatTally({ rounds, winner }) {
  return `rounds ${rounds.length}\n${outcome(winner)}\n`
}

function outcome(winner) {
  return winner === null ? 'no winner' : `winner ${winner}`
}
"}

