 * URI reference parsing, normalization and reference resolution
 * following RFC 3986's generic syntax.
 */

export class UriError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

const DEFAULT_PORTS = new Map([
  ['http', '80'],
  ['ws', '80'],
  ['https', '443'],
  ['wss', '443'],
  ['ftp', '21'],
])

const HEX = /^[0-9A-Fa-f]{2}$/

/** Parse an authority into userinfo, host and port. */
function parseAuthority(authority) {
  let userinfo = null
  let rest = authority
  const at = authority.lastIndexOf('@')
  if (at !== -1) {
    userinfo = authority.slice(0, at)
    rest = authority.slice(at + 1)
  }
  const bracket = rest.lastIndexOf(']')
  const colon = rest.indexOf(':', bracket + 1)
  let host = rest
  let port = null
  if (colon !== -1) {
    host = rest.slice(0, colon)
    port = rest.slice(colon + 1)
  }
  return { userinfo, host, port }
}

function formatAuthority({ userinfo, host, port }) {
  let out = ''
  if (userinfo !== null) out += userinfo + '@'
  out += host
  if (port !== null) out += ':' + port
  return out
}

/** Parse a URI reference into its five generic components. */
export function parse(reference) {
  let rest = reference
  let scheme = null

  const colon = rest.indexOf(':')
  if (colon !== -1) {
    const head = rest.slice(0, colon)
    if (!/[/?#]/.test(head)) {
      scheme = head
      rest = rest.slice(colon + 1)
    }
  }

  let fragment = null
  const hash = rest.indexOf('#')
  if (hash !== -1) {
    fragment = rest.slice(hash + 1)
    rest = rest.slice(0, hash)
  }

  let query = null
  const question = rest.indexOf('?')
  if (question !== -1) {
    query = rest.slice(question + 1)
    rest = rest.slice(0, question)
  }

  let authority = null
  if (rest.startsWith('//')) {
    rest = rest.slice(2)
    const end = rest.search(/[/?#]/)
    if (end === -1) {
      authority = rest
      rest = ''
    } else {
      authority = rest.slice(0, end)
      rest = rest.slice(end)
    }
  }

  return { scheme, authority, path: rest, query, fragment }
}

export function format({ scheme, authority, path, query, fragment }) {
  let out = ''
  if (scheme !== null) out += scheme + ':'
  if (authority !== null) out += '//' + authority
  out += path
  if (query !== null) out += '?' + query
  if (fragment !== null) out += '#' + fragment
  return out
}

const UNRESERVED = /[A-Za-z0-9\-._~]/

/** Uppercase percent triplets and decode unreserved ones. */
function normalizePercent(text, component) {
  let out = ''
  for (let i = 0; i < text.length; i++) {
    const ch = text[i]
    if (ch !== '%') {
      out += ch
      continue
    }
    const digits = text.slice(i + 1, i + 3)
    if (digits.length < 2 || !HEX.test(digits)) throw new UriError(component)
    const code = parseInt(digits, 16)
    const decoded = String.fromCharCode(code)
    if (UNRESERVED.test(decoded)) out += decoded
    else out += '%' + digits.toUpperCase()
    i += 2
  }
  return out
}

function asciiLower(text) {
  let out = ''
  for (const ch of text) {
    const code = ch.charCodeAt(0)
    out += code >= 65 && code <= 90 ? String.fromCharCode(code + 32) : ch
  }
  return out
}

/** RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length > 0) {
    if (input.startsWith('../')) input = input.slice(3)
    else if (input.startsWith('./')) input = input.slice(2)
    else if (input.startsWith('/./')) input = '/' + input.slice(3)
    else if (input === '/.') input = '/'
    else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      const cut = output.lastIndexOf('/')
      output = cut === -1 ? '' : output.slice(0, cut)
    } else if (input === '/..') {
      input = '/'
      const cut = output.lastIndexOf('/')
      output = cut === -1 ? '' : output.slice(0, cut)
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let end = input.indexOf('/', input.startsWith('/') ? 1 : 0)
      if (end === -1) end = input.length
      output += input.slice(0, end)
      input = input.slice(end)
    }
  }
  return output
}

/**
 * Check every component for truncated percent-encodings, in the order
 * the specification names them.
 */
export function checkPercent(parts) {
  const authority = parts.authority === null ? null : parseAuthority(parts.authority)
  const checks = [
    ['path', parts.path],
    ['userinfo', authority === null ? null : authority.userinfo],
    ['host', authority === null ? null : authority.host],
    ['query', parts.query],
    ['fragment', parts.fragment],
  ]
  for (const [name, value] of checks) {
    if (value === null || value === undefined) continue
    normalizePercent(value, name)
  }
}

/** Normalize the parsed components of a URI reference. */
export function normalizeParts(parts) {
  let { scheme, authority, path, query, fragment } = parts

  checkPercent(parts)

  if (scheme !== null) scheme = asciiLower(scheme)

  if (authority !== null) {
    const bits = parseAuthority(authority)
    if (bits.userinfo !== null) bits.userinfo = normalizePercent(bits.userinfo, 'userinfo')
    bits.host = asciiLower(normalizePercent(bits.host, 'host'))
    if (bits.port !== null) {
      const fallback = scheme === null ? undefined : DEFAULT_PORTS.get(scheme)
      if (bits.port === '' || (fallback !== undefined && bits.port === fallback)) bits.port = null
    }
    authority = formatAuthority(bits)
  }

  path = normalizePercent(path, 'path')
  if (query !== null) query = normalizePercent(query, 'query')
  if (fragment !== null) fragment = normalizePercent(fragment, 'fragment')

  path = removeDotSegments(path)
  if (authority !== null && path === '') path = '/'

  return { scheme, authority, path, query, fragment }
}

export function normalize(reference) {
  return format(normalizeParts(parse(reference)))
}

function merge(base, refPath) {
  if (base.authority !== null && base.path === '') return '/' + refPath
  const cut = base.path.lastIndexOf('/')
  if (cut === -1) return refPath
  return base.path.slice(0, cut + 1) + refPath
}

/** RFC 3986 section 5.2.2, strict. */
export function resolveParts(base, ref) {
  if (ref.scheme !== null) {
    return {
      scheme: ref.scheme,
      authority: ref.authority,
      path: removeDotSegments(ref.path),
      query: ref.query,
      fragment: ref.fragment,
    }
  }
  if (ref.authority !== null) {
    return {
      scheme: base.scheme,
      authority: ref.authority,
      path: removeDotSegments(ref.path),
      query: ref.query,
      fragment: ref.fragment,
    }
  }
  if (ref.path === '') {
    return {
      scheme: base.scheme,
      authority: base.authority,
      path: base.path,
      query: ref.query !== null ? ref.query : base.query,
      fragment: ref.fragment,
    }
  }
  const path = ref.path.startsWith('/')
    ? removeDotSegments(ref.path)
    : removeDotSegments(merge(base, ref.path))
  return {
    scheme: base.scheme,
    authority: base.authority,
    path,
    query: ref.query,
    fragment: ref.fragment,
  }
}

export function resolve(baseText, refText) {
  const base = parse(baseText)
  const ref = parse(refText)
  checkPercent(base)
  checkPercent(ref)
  return format(normalizeParts(resolveParts(base, ref)))
}
"}

