{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { normalize, parse, resolve, UriError } from './uri.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const argv = process.argv.slice(2)
if (argv.length !== 1 || (argv[0] !== 'normalize' && argv[0] !== 'resolve')) {
  fail('usage: cli.js normalize|resolve')
}
const mode = argv[0]

let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch {
  input = ''
}

const records = input.split('\n')
if (records.length > 0 && records[records.length - 1] === '') records.pop()

const lines = []
for (let i = 0; i < records.length; i++) {
  const record = records[i]
  const number = i + 1
  try {
    if (mode === 'normalize') {
      lines.push(normalize(record))
    } else {
      const space = record.indexOf(' ')
      if (space === -1) fail(`line ${number}: expected a base and a reference`)
      const baseText = record.slice(0, space)
      const refText = record.slice(space + 1)
      if (parse(baseText).scheme === null) fail(`line ${number}: the base has no scheme`)
      lines.push(resolve(baseText, refText))
    }
  } catch (error) {
    if (error instanceof UriError) fail(`line ${number}: ${error.message}`)
    throw error
  }
}

process.stdout.write(lines.map((line) => line + '\n').join(''))
"}

