import { parseAddress, addressName, compareCells } from './address.js'
import { parseFormula } from './formula.js'
import * as V from './value.js'

const VARIADIC = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
const FUNCTIONS = [...VARIADIC, 'ABS', 'IF']

/** The cells a range covers, in ascending column and then row order. */
function rangeCells(node) {
  const from = parseAddress(node.from)
  const to = parseAddress(node.to)
  if (from === null || to === null) return null
  const cells = []
  const firstCol = Math.min(from.col, to.col)
  const lastCol = Math.max(from.col, to.col)
  const firstRow = Math.min(from.row, to.row)
  const lastRow = Math.max(from.row, to.row)
  for (let col = firstCol; col <= lastCol; col += 1) {
    for (let row = firstRow; row <= lastRow; row += 1) {
      cells.push({ col, row, name: addressName(col, row) })
    }
  }
  return cells
}

export class Sheet {
  constructor(parsed) {
    this.cells = parsed.cells
    this.order = parsed.order
    this.values = new Map()
    this.running = new Set()
    this.trees = new Map()
  }

  /** The tree of a cell's formula, null when the grammar refused it. */
  tree(cell) {
    if (!this.trees.has(cell.name)) {
      this.trees.set(cell.name, cell.content.startsWith('=') ? parseFormula(cell.content.slice(1)) : null)
    }
    return this.trees.get(cell.name)
  }

  /** The value of the named cell; cells nobody declared read as zero. */
  value(name) {
    if (this.values.has(name)) return this.values.get(name)
    const cell = this.cells.get(name)
    if (cell === undefined) return V.ZERO
    if (this.running.has(name)) return V.CYCLE
    this.running.add(name)
    let value
    try {
      if (!cell.content.startsWith('=')) {
        value = V.literalValue(cell.content)
      } else {
        const tree = this.tree(cell)
        value = tree === null ? V.ERR : this.eval(tree)
      }
    } finally {
      this.running.delete(name)
    }
    this.values.set(name, value)
    return value
  }

  eval(node) {
    switch (node.kind) {
      case 'number':
        return V.number(node.value)
      case 'boolean':
        return V.boolean(node.value)
      case 'group':
        return this.eval(node.inner)
      case 'range':
        // A range is only meaningful directly as a function argument.
        return V.ERR
      case 'reference': {
        const address = parseAddress(node.text)
        return address === null ? V.REF : this.value(address.name)
      }
      case 'unary':
        return this.unary(node)
      case 'binary':
        return this.binary(node)
      default:
        return this.call(node)
    }
  }

  unary(node) {
    const operand = V.asNumber(this.eval(node.operand))
    if (V.isError(operand)) return operand
    return V.finite(node.op === '-' ? -operand.number : operand.number)
  }

  binary(node) {
    const left = this.eval(node.left)
    if (V.isError(left)) return left
    const right = this.eval(node.right)
    if (V.isError(right)) return right
    if (['=', '<>', '<', '<=', '>', '>='].includes(node.op)) {
      const order = V.compareValues(left, right)
      switch (node.op) {
        case '=':
          return V.boolean(order === 0)
        case '<>':
          return V.boolean(order !== 0)
        case '<':
          return V.boolean(order < 0)
        case '<=':
          return V.boolean(order <= 0)
        case '>':
          return V.boolean(order > 0)
        default:
          return V.boolean(order >= 0)
      }
    }
    const a = V.asNumber(left)
    if (V.isError(a)) return a
    const b = V.asNumber(right)
    if (V.isError(b)) return b
    switch (node.op) {
      case '+':
        return V.finite(a.number + b.number)
      case '-':
        return V.finite(a.number - b.number)
      case '*':
        return V.finite(a.number * b.number)
      case '/':
        return b.number === 0 ? V.DIV0 : V.finite(a.number / b.number)
      default:
        return V.finite(a.number ** b.number)
    }
  }

  /** The values an argument stands for, with ranges expanded. */
  argumentValues(node) {
    if (node.kind !== 'range') return [this.eval(node)]
    const cells = rangeCells(node)
    if (cells === null) return [V.REF]
    return cells.map((cell) => this.value(cell.name))
  }

  call(node) {
    const name = node.name.toUpperCase()
    if (!FUNCTIONS.includes(name)) return V.NAME
    if (name === 'IF') return this.callIf(node)
    const values = node.args.flatMap((argument) => this.argumentValues(argument))
    if (name === 'ABS' ? values.length !== 1 : values.length < 1) return V.ERR
    const failure = values.find(V.isError)
    if (failure !== undefined) return failure
    if (name === 'COUNT') return V.number(values.filter((value) => value.kind === 'number').length)
    const numbers = []
    for (const value of values) {
      const n = V.asNumber(value)
      if (V.isError(n)) return n
      numbers.push(n.number)
    }
    switch (name) {
      case 'SUM':
        return V.finite(numbers.reduce((total, n) => total + n, 0))
      case 'MIN':
        return V.finite(Math.min(...numbers))
      case 'MAX':
        return V.finite(Math.max(...numbers))
      case 'AVG':
        return V.finite(numbers.reduce((total, n) => total + n, 0) / numbers.length)
      default:
        return V.finite(Math.abs(numbers[0]))
    }
  }

  /** `IF` reads only the branch it takes, so the other one's errors stay unseen. */
  callIf(node) {
    if (node.args.length !== 3) return V.ERR
    const condition = this.single(node.args[0])
    if (V.isError(condition)) return condition
    let taken
    if (condition.kind === 'boolean') taken = condition.boolean
    else if (condition.kind === 'number') taken = condition.number !== 0
    else return V.VALUE
    return this.single(node.args[taken ? 1 : 2])
  }

  /** One argument read as a single value. */
  single(node) {
    const values = this.argumentValues(node)
    const failure = values.find(V.isError)
    if (failure !== undefined) return failure
    return values.length === 1 ? values[0] : V.ERR
  }

  /** The distinct cells a cell's content names directly, ranges expanded. */
  deps(cell) {
    if (!cell.content.startsWith('=')) return []
    const tree = this.tree(cell)
    if (tree === null) return []
    const found = new Map()
    const walk = (node) => {
      switch (node.kind) {
        case 'reference': {
          const address = parseAddress(node.text)
          if (address !== null) found.set(address.name, address)
          break
        }
        case 'range': {
          const cells = rangeCells(node)
          if (cells !== null) for (const one of cells) found.set(one.name, one)
          break
        }
        case 'group':
          walk(node.inner)
          break
        case 'unary':
          walk(node.operand)
          break
        case 'binary':
          walk(node.left)
          walk(node.right)
          break
        case 'call':
          for (const argument of node.args) walk(argument)
          break
        default:
          break
      }
    }
    walk(tree)
    return [...found.values()].sort(compareCells)
  }
}
