{"file_path":"src/schedule.js","content":"/**
 * The list scheduler behind `pack`.
 */

import { priorities } from './graph.js'

/**
 * Runs the graph on `count` workers, greedily starting the ready task of the
 * greatest priority, ties broken by ascending name, on the free worker of the
 * smallest index. Returns each worker's runs and the makespan.
 */
export function pack(graph, count) {
  const priority = priorities(graph)
  const workers = []
  for (let i = 0; i < count; i += 1) workers.push({ free: 0, runs: [] })

  const pending = new Set(graph.keys())
  const finish = new Map()
  let now = 0
  let makespan = 0

  while (pending.size > 0) {
    let started = true
    while (started) {
      started = false
      const worker = workers.find((candidate) => candidate.free <= now)
      if (worker === undefined) break
      let best = null
      for (const name of pending) {
        const task = graph.get(name)
        if (!task.deps.every((dependency) => finish.has(dependency) && finish.get(dependency) <= now)) continue
        if (best === null || priority.get(name) > priority.get(best)) best = name
      }
      if (best === null) break
      const task = graph.get(best)
      const end = now + task.cost
      worker.runs.push({ name: best, start: now, finish: end })
      worker.free = end
      finish.set(best, end)
      pending.delete(best)
      if (end > makespan) makespan = end
      started = true
    }
    if (pending.size === 0) break
    const later = workers.map((worker) => worker.free).filter((time) => time > now)
    if (later.length === 0) break
    now = Math.min(...later)
  }

  return { workers, makespan }
}
"}

