{"file_path":"src/policies.js","content":"/**
 * The two limiter policies. Each keeps one independent state per key, and each
 * answers the same three questions: advance to a tick, allow, record.
 */

/**
 * A token bucket. It holds `capacity` tokens per key and starts full. Tokens
 * are counted as an exact fraction with `per` as its denominator, so that the
 * partial periods of a refill accumulate without ever being rounded away.
 */
export class Bucket {
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.full = capacity * per
    this.keys = new Map()
  }

  state(key, tick) {
    let state = this.keys.get(key)
    if (state === undefined) {
      state = { tokens: this.full, tick }
      this.keys.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.state(key, tick)
    const tokens = state.tokens + this.refill * (tick - state.tick)
    state.tokens = tokens > this.full ? this.full : tokens
    state.tick = tick
  }

  allows(key, tick) {
    return this.state(key, tick).tokens >= this.per
  }

  record(key, tick) {
    const state = this.state(key, tick)
    state.tokens -= this.per
  }
}

/**
 * A sliding window. It remembers the ticks of the requests it recorded for a
 * key and forgets those that have left the `span` ticks ending at the current
 * one.
 */
export class Window {
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit
    this.span = span
    this.keys = new Map()
  }

  state(key) {
    let state = this.keys.get(key)
    if (state === undefined) {
      state = []
      this.keys.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.state(key)
    const edge = tick - this.span
    let kept = 0
    while (kept < state.length && state[kept] <= edge) kept += 1
    if (kept > 0) state.splice(0, kept)
  }

  allows(key) {
    return BigInt(this.state(key).length) < this.limit
  }

  record(key, tick) {
    this.state(key).push(tick)
  }
}
"}

