{"file_path":"src/parse.js","content":"/**
 * The reader of a limiter file: it turns the text into the declared policies,
 * the routes and the log of events, and refuses anything the grammar does not
 * allow.
 */

import { Bucket, Window } from './policies.js'

/** A refusal carrying the message the command writes to standard error. */
export class ParseError extends Error {}

const NAME = /^[A-Za-z0-9_./:-]+$/
const INTEGER = /^(?:0|[1-9][0-9]*)$/

function fail(line, reason) {
  throw new ParseError(`line ${line}: ${reason}`)
}

function isName(word) {
  return NAME.test(word)
}

function integer(word, field, least, line) {
  if (!INTEGER.test(word)) fail(line, `${field} must be an integer of at least ${least}`)
  const value = BigInt(word)
  if (value < least) fail(line, `${field} must be an integer of at least ${least}`)
  return value
}

/** Splits the input into its lines, dropping the tail a trailing newline leaves. */
export function lines(input) {
  const split = input.split('\n')
  if (split.length > 0 && split[split.length - 1] === '') split.pop()
  return split
}

/**
 * Parses a whole limiter file. Returns the policies by name, the routes sorted
 * so that the longest prefix wins, and the events in log order.
 */
export function parse(input) {
  const policies = new Map()
  const routes = new Map()
  const events = []
  let started = false
  let last = null

  const numbers = lines(input)
  for (let index = 0; index < numbers.length; index += 1) {
    const line = index + 1
    const text = numbers[index].trim()
    if (text === '' || text.startsWith('#')) continue
    const words = text.split(/\s+/)
    const directive = words[0]

    if (directive === 'bucket' || directive === 'window') {
      const shape =
        directive === 'bucket'
          ? 'expected bucket <name> <capacity> <refill> <per>'
          : 'expected window <name> <limit> <span>'
      if (words.length !== (directive === 'bucket' ? 5 : 4)) fail(line, shape)
      const name = words[1]
      if (!isName(name)) fail(line, `invalid policy name ${name}`)
      if (policies.has(name)) fail(line, `policy ${name} is declared twice`)
      if (started) fail(line, 'declarations must come before the first event')
      if (directive === 'bucket') {
        const capacity = integer(words[2], 'capacity', 1n, line)
        const refill = integer(words[3], 'refill', 0n, line)
        const per = integer(words[4], 'per', 1n, line)
        policies.set(name, new Bucket(name, capacity, refill, per))
      } else {
        const limit = integer(words[2], 'limit', 0n, line)
        const span = integer(words[3], 'span', 1n, line)
        policies.set(name, new Window(name, limit, span))
      }
      continue
    }

    if (directive === 'route') {
      if (words.length < 3) fail(line, 'expected route <prefix> <policy>...')
      const prefix = words[1]
      if (!isName(prefix)) fail(line, `invalid route prefix ${prefix}`)
      if (routes.has(prefix)) fail(line, `prefix ${prefix} is routed twice`)
      const chosen = []
      for (const name of words.slice(2)) {
        const policy = policies.get(name)
        if (policy === undefined) fail(line, `unknown policy ${name}`)
        chosen.push(policy)
      }
      if (started) fail(line, 'declarations must come before the first event')
      routes.set(prefix, chosen)
      continue
    }

    if (directive === 'event') {
      if (words.length !== 3) fail(line, 'expected event <tick> <key>')
      const key = words[2]
      if (!isName(key)) fail(line, `invalid key ${key}`)
      const tick = integer(words[1], 'tick', 0n, line)
      if (last !== null && tick < last) fail(line, `tick ${tick} is before tick ${last}`)
      last = tick
      started = true
      events.push({ tick, key })
      continue
    }

    fail(line, `unknown directive ${directive}`)
  }

  const sorted = [...routes.entries()].sort((a, b) => b[0].length - a[0].length)
  return { policies, routes: sorted, events }
}
"}

