{"file_path":"src/simulate.js","content":"/**
 * The run of a limiter file: every event is put to the policies of its route
 * and answered with a verdict.
 */

/** Finds the policies of the longest declared prefix the key starts with. */
function route(routes, key) {
  for (const [prefix, policies] of routes) {
    if (key.startsWith(prefix)) return policies
  }
  return []
}

/**
 * Answers every event in log order. A verdict is `{ tick, key, policy }`, where
 * `policy` is the name of the first policy of the route that refused, or null
 * when the event was allowed.
 */
export function simulate({ routes, events }) {
  const verdicts = []
  for (const { tick, key } of events) {
    const policies = route(routes, key)
    for (const policy of policies) policy.advance(key, tick)
    let refused = null
    for (const policy of policies) {
      if (!policy.allows(key, tick)) {
        refused = policy.name
        break
      }
    }
    if (refused === null) {
      for (const policy of policies) policy.record(key, tick)
    }
    verdicts.push({ tick, key, policy: refused })
  }
  return verdicts
}

/** Renders one line per verdict, in log order. */
export function replay(verdicts) {
  return verdicts
    .map(({ tick, key, policy }) => `${tick} ${key} ${policy === null ? 'allow' : `deny ${policy}`}\n`)
    .join('')
}

/** Renders the verdict counts of every key that saw an event, and the totals. */
export function summary(verdicts) {
  const keys = new Map()
  let allowed = 0
  let denied = 0
  for (const { key, policy } of verdicts) {
    let counts = keys.get(key)
    if (counts === undefined) {
      counts = { allowed: 0, denied: 0 }
      keys.set(key, counts)
    }
    if (policy === null) {
      counts.allowed += 1
      allowed += 1
    } else {
      counts.denied += 1
      denied += 1
    }
  }
  let out = ''
  for (const key of [...keys.keys()].sort()) {
    const counts = keys.get(key)
    out += `${key} allowed=${counts.allowed} denied=${counts.denied}\n`
  }
  return `${out}total allowed=${allowed} denied=${denied}\n`
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { ParseError, parse } from './parse.js'
import { replay, simulate, summary } from './simulate.js'

function main(argv) {
  const mode = argv.length === 1 ? argv[0] : null
  if (mode !== 'replay' && mode !== 'summary') {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    return 2
  }
  let input = ''
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }
  let out
  try {
    const verdicts = simulate(parse(input))
    out = mode === 'replay' ? replay(verdicts) : summary(verdicts)
  } catch (error) {
    if (!(error instanceof ParseError)) throw error
    process.stderr.write(`error: ${error.message}\n`)
    return 2
  }
  process.stdout.write(out)
  return 0
}

process.exitCode = main(process.argv.slice(2))
"}

