{"file_path":"src/parse.js","content":"/** Parsing and validation of the limiter file. */

const NAME_RE = /^[A-Za-z0-9_./:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

function isName(word) {
  return NAME_RE.test(word)
}

function integerAtLeast(word, field, least, line) {
  if (!INT_RE.test(word)) {
    throw new ParseError(line, `${field} must be an integer of at least ${least}`)
  }
  const value = BigInt(word)
  if (value < BigInt(least)) {
    throw new ParseError(line, `${field} must be an integer of at least ${least}`)
  }
  return value
}

/**
 * Parses the whole file. Returns { policies, routes, events }.
 */
export function parse(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (events.length > 0) {
        throw new ParseError(lineNo, 'declarations must come before the first event')
      }
    }

    if (directive === 'bucket') {
      if (words.length !== 5) {
        throw new ParseError(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      }
      const name = words[1]
      if (!isName(name)) throw new ParseError(lineNo, `invalid policy name ${name}`)
      if (policies.has(name)) throw new ParseError(lineNo, `policy ${name} is declared twice`)
      const capacity = integerAtLeast(words[2], 'capacity', 1, lineNo)
      const refill = integerAtLeast(words[3], 'refill', 0, lineNo)
      const per = integerAtLeast(words[4], 'per', 1, lineNo)
      policies.set(name, { kind: 'bucket', name, capacity, refill, per })
    } else if (directive === 'window') {
      if (words.length !== 4) {
        throw new ParseError(lineNo, 'expected window <name> <limit> <span>')
      }
      const name = words[1]
      if (!isName(name)) throw new ParseError(lineNo, `invalid policy name ${name}`)
      if (policies.has(name)) throw new ParseError(lineNo, `policy ${name} is declared twice`)
      const limit = integerAtLeast(words[2], 'limit', 0, lineNo)
      const span = integerAtLeast(words[3], 'span', 1, lineNo)
      policies.set(name, { kind: 'window', name, limit, span })
    } else if (directive === 'route') {
      if (words.length < 3) {
        throw new ParseError(lineNo, 'expected route <prefix> <policy>...')
      }
      const prefix = words[1]
      if (!isName(prefix)) throw new ParseError(lineNo, `invalid route prefix ${prefix}`)
      if (routes.has(prefix)) throw new ParseError(lineNo, `prefix ${prefix} is routed twice`)
      const named = []
      for (const word of words.slice(2)) {
        if (!isName(word)) throw new ParseError(lineNo, `invalid policy name ${word}`)
        if (!policies.has(word)) throw new ParseError(lineNo, `unknown policy ${word}`)
        named.push(policies.get(word))
      }
      routes.set(prefix, named)
    } else if (directive === 'event') {
      if (words.length !== 3) {
        throw new ParseError(lineNo, 'expected event <tick> <key>')
      }
      const tick = integerAtLeast(words[1], 'tick', 0, lineNo)
      const key = words[2]
      if (!isName(key)) throw new ParseError(lineNo, `invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) {
        throw new ParseError(lineNo, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      events.push({ tick, text: words[1], key })
    } else {
      throw new ParseError(lineNo, `unknown directive ${directive}`)
    }
  }

  return { policies, routes, events }
}
"}

{"file_path":"src/simulate.js","content":"/** The limiter policies and the simulation of the event log. */

class Bucket {
  constructor(spec) {
    this.name = spec.name
    this.capacity = spec.capacity
    this.refill = spec.refill
    this.per = spec.per
    this.states = new Map()
  }

  state(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      // Tokens are held scaled by `per`, so refills are exact.
      state = { tokens: this.capacity * this.per, last: null }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.state(key)
    if (state.last === null) {
      state.last = tick
      return
    }
    const elapsed = tick - state.last
    state.last = tick
    if (elapsed <= 0n) return
    const cap = this.capacity * this.per
    state.tokens += this.refill * elapsed
    if (state.tokens > cap) state.tokens = cap
  }

  allows(key) {
    return this.state(key).tokens >= this.per
  }

  record(key) {
    this.state(key).tokens -= this.per
  }
}

class Window {
  constructor(spec) {
    this.name = spec.name
    this.limit = spec.limit
    this.span = spec.span
    this.states = new Map()
  }

  state(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { ticks: [] }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.state(key)
    const cutoff = tick - this.span
    let drop = 0
    while (drop < state.ticks.length && state.ticks[drop] <= cutoff) drop++
    if (drop > 0) state.ticks.splice(0, drop)
  }

  allows(key) {
    return BigInt(this.state(key).ticks.length) < this.limit
  }

  record(key, tick) {
    this.state(key).ticks.push(tick)
  }
}

function build(spec) {
  return spec.kind === 'bucket' ? new Bucket(spec) : new Window(spec)
}

/**
 * Runs the log, returning one verdict per event in log order.
 */
export function simulate({ policies, routes, events }) {
  const runtime = new Map()
  for (const [name, spec] of policies) runtime.set(name, build(spec))

  const prefixes = [...routes.keys()]
  const verdicts = []

  for (const event of events) {
    let best = null
    for (const prefix of prefixes) {
      if (event.key.startsWith(prefix) && (best === null || prefix.length > best.length)) {
        best = prefix
      }
    }
    const chain = best === null ? [] : routes.get(best).map((spec) => runtime.get(spec.name))

    for (const policy of chain) policy.advance(event.key, event.tick)
    let denier = null
    for (const policy of chain) {
      if (!policy.allows(event.key)) {
        denier = policy.name
        break
      }
    }
    if (denier === null) {
      for (const policy of chain) policy.record(event.key, event.tick)
    }
    verdicts.push({ tick: event.text, key: event.key, denier })
  }

  return verdicts
}

export function renderReplay(verdicts) {
  return verdicts
    .map((v) => (v.denier === null ? `${v.tick} ${v.key} allow\n` : `${v.tick} ${v.key} deny ${v.denier}\n`))
    .join('')
}

export function renderSummary(verdicts) {
  const perKey = new Map()
  let allowed = 0
  let denied = 0
  for (const v of verdicts) {
    let counts = perKey.get(v.key)
    if (counts === undefined) {
      counts = { allowed: 0, denied: 0 }
      perKey.set(v.key, counts)
    }
    if (v.denier === null) {
      counts.allowed++
      allowed++
    } else {
      counts.denied++
      denied++
    }
  }
  const keys = [...perKey.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  let out = ''
  for (const key of keys) {
    const counts = perKey.get(key)
    out += `${key} allowed=${counts.allowed} denied=${counts.denied}\n`
  }
  out += `total allowed=${allowed} denied=${denied}\n`
  return out
}
"}

