{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { parse, ParseError } from './parse.js'
import { simulate, renderReplay, renderSummary } from './simulate.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main(argv) {
  if (argv.length !== 1 || (argv[0] !== 'replay' && argv[0] !== 'summary')) {
    fail('usage: cli.js replay|summary')
  }
  let text = ''
  try {
    text = readFileSync(0, 'utf8')
  } catch {
    text = ''
  }
  let program
  try {
    program = parse(text)
  } catch (error) {
    if (error instanceof ParseError) fail(error.message)
    throw error
  }
  const verdicts = simulate(program)
  process.stdout.write(argv[0] === 'replay' ? renderReplay(verdicts) : renderSummary(verdicts))
}

main(process.argv.slice(2))
"}

