{"file_path":"src/render.js","content":"/**
 * The two ways the document comes back out: canonical JSON, and the flat list
 * of paths with their types.
 */
import { pathJoin } from './errors.js'

/** Ascending order by code point, which surrogate pairs would upset. */
function byCodePoint(a, b) {
  const x = [...a]
  const y = [...b]
  for (let i = 0; i < x.length && i < y.length; i += 1) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d !== 0) return d
  }
  return x.length - y.length
}

function sortedKeys(table) {
  return [...table.entries.keys()].sort(byCodePoint)
}

export function toJson(node) {
  return `${render(node, '')}\n`
}

function render(node, indent) {
  if (node.kind === 'table') {
    const keys = sortedKeys(node)
    if (keys.length === 0) return '{}'
    const inner = indent + '  '
    const members = keys.map(
      (key) => `${inner}${JSON.stringify(key)}: ${render(node.entries.get(key), inner)}`,
    )
    return `{\n${members.join(',\n')}\n${indent}}`
  }
  if (node.kind === 'array') {
    if (node.items.length === 0) return '[]'
    const inner = indent + '  '
    const items = node.items.map((item) => `${inner}${render(item, inner)}`)
    return `[\n${items.join(',\n')}\n${indent}]`
  }
  if (node.kind === 'string') return JSON.stringify(node.value)
  if (node.kind === 'boolean') return node.value ? 'true' : 'false'
  return JSON.stringify(node.value)
}

export function toKeys(root) {
  const out = []
  walk(root, '', out)
  return out.map((line) => `${line}\n`).join('')
}

function walk(node, prefix, out) {
  if (node.kind === 'table') {
    for (const key of sortedKeys(node)) {
      const child = node.entries.get(key)
      const path = pathJoin(prefix, key)
      out.push(`${path} ${child.kind}`)
      walk(child, path, out)
    }
    return
  }
  if (node.kind === 'array') {
    node.items.forEach((item, i) => {
      const path = `${prefix}[${i}]`
      out.push(`${path} ${item.kind}`)
      walk(item, path, out)
    })
  }
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import { readFileSync } from 'node:fs'
import { ConfError } from './errors.js'
import { parse } from './parse.js'
import { toJson, toKeys } from './render.js'

function main(argv) {
  const mode = argv.length === 1 ? argv[0] : ''
  if (mode !== 'json' && mode !== 'keys') {
    process.stderr.write('error: usage: cli.js json|keys\n')
    return 2
  }

  let input = ''
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }

  let out
  try {
    const root = parse(input)
    out = mode === 'json' ? toJson(root) : toKeys(root)
  } catch (err) {
    if (!(err instanceof ConfError)) throw err
    process.stderr.write(`error: line ${err.line}: ${err.reason}\n`)
    return 2
  }

  process.stdout.write(out)
  return 0
}

process.exitCode = main(process.argv.slice(2))
"}

