{"file_path":"src/lexer.js","content":"/**
 * The scanner. `scan(source)` turns UTF-8 source text into a list of tokens,
 * or throws a `ScanError` carrying the position and the reason of the first
 * failure it meets.
 */

export class ScanError extends Error {
  constructor(line, column, reason) {
    super(`${line}:${column}: ${reason}`)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCTUATION = [
  '==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.',
]

const TAB_WIDTH = 4

function isDigit(c) {
  return c >= '0' && c <= '9'
}

function isLetter(c) {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

function isIdentStart(c) {
  return c !== undefined && (isLetter(c) || c === '_')
}

function isIdentPart(c) {
  return c !== undefined && (isLetter(c) || isDigit(c) || c === '_')
}

function isHexDigit(c) {
  return c !== undefined && (isDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))
}

function digitTest(base) {
  if (base === 16) return isHexDigit
  if (base === 8) return (c) => c !== undefined && c >= '0' && c <= '7'
  if (base === 2) return (c) => c === '0' || c === '1'
  return (c) => c !== undefined && isDigit(c)
}

class Scanner {
  constructor(source) {
    this.chars = Array.from(source)
    this.index = 0
    this.line = 1
    this.column = 1
  }

  get done() {
    return this.index >= this.chars.length
  }

  peek(offset = 0) {
    return this.chars[this.index + offset]
  }

  /** Reads one code point, keeping the line and column counts up to date. */
  advance() {
    const c = this.chars[this.index]
    this.index += 1
    if (c === '\n') {
      this.line += 1
      this.column = 1
    } else if (c === '\t') {
      this.column = Math.floor((this.column - 1) / TAB_WIDTH) * TAB_WIDTH + TAB_WIDTH + 1
    } else {
      this.column += 1
    }
    return c
  }

  mark() {
    return { index: this.index, line: this.line, column: this.column }
  }

  textFrom(start) {
    return this.chars.slice(start.index, this.index).join('')
  }

  error(at, reason) {
    return new ScanError(at.line, at.column, reason)
  }

  scan() {
    const tokens = []
    for (;;) {
      this.skipBlanksAndComments()
      if (this.done) return tokens
      tokens.push(this.scanToken())
    }
  }

  skipBlanksAndComments() {
    for (;;) {
      const c = this.peek()
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '/') {
        while (!this.done && this.peek() !== '\n') this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '*') {
        this.skipBlockComment()
        continue
      }
      return
    }
  }

  skipBlockComment() {
    const start = this.mark()
    let depth = 0
    for (;;) {
      if (this.done) throw this.error(start, 'unterminated block comment')
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.advance()
        this.advance()
        depth += 1
        continue
      }
      if (this.peek() === '*' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        depth -= 1
        if (depth === 0) return
        continue
      }
      this.advance()
    }
  }

  scanToken() {
    const start = this.mark()
    const c = this.peek()

    if (c === 'r' && this.peek(1) === '"') return this.scanRawString(start)
    if (isIdentStart(c)) return this.scanWord(start)
    if (isDigit(c)) return this.scanNumber(start)
    if (c === '"') return this.scanString(start)

    for (const punct of PUNCTUATION) {
      if (this.matches(punct)) {
        for (let i = 0; i < punct.length; i += 1) this.advance()
        return { kind: 'punct', line: start.line, column: start.column, text: punct }
      }
    }

    throw this.error(start, `unexpected character ${c}`)
  }

  matches(text) {
    const wanted = Array.from(text)
    for (let i = 0; i < wanted.length; i += 1) {
      if (this.peek(i) !== wanted[i]) return false
    }
    return true
  }

  scanWord(start) {
    while (isIdentPart(this.peek())) this.advance()
    const text = this.textFrom(start)
    return {
      kind: KEYWORDS.has(text) ? 'keyword' : 'ident',
      line: start.line,
      column: start.column,
      text,
    }
  }

  /** Consumes a run of digits of one base, allowing `_` between two digits. */
  digitRun(isBaseDigit) {
    if (!isBaseDigit(this.peek())) return false
    this.advance()
    for (;;) {
      const c = this.peek()
      if (isBaseDigit(c)) {
        this.advance()
        continue
      }
      if (c === '_' && isBaseDigit(this.peek(1))) {
        this.advance()
        this.advance()
        continue
      }
      return true
    }
  }

  badNumber(start) {
    while (isIdentPart(this.peek())) this.advance()
    throw this.error(start, `invalid number ${this.textFrom(start)}`)
  }

  scanNumber(start) {
    const prefix = this.peek() === '0' ? this.peek(1) : undefined
    let base = 10
    if (prefix === 'x' || prefix === 'X') base = 16
    else if (prefix === 'b' || prefix === 'B') base = 2
    else if (prefix === 'o' || prefix === 'O') base = 8

    if (base !== 10) {
      this.advance()
      this.advance()
      if (!this.digitRun(digitTest(base))) this.badNumber(start)
    } else {
      const decimal = digitTest(10)
      this.digitRun(decimal)
      if (this.peek() === '.' && isDigit(this.peek(1))) {
        this.advance()
        this.digitRun(decimal)
      }
      const marker = this.peek()
      if (marker === 'e' || marker === 'E') {
        const next = this.peek(1)
        const signed = next === '+' || next === '-'
        if (isDigit(next) || (signed && isDigit(this.peek(2)))) {
          this.advance()
          if (signed) this.advance()
          this.digitRun(decimal)
        }
      }
    }

    if (isIdentPart(this.peek())) this.badNumber(start)
    return { kind: 'number', line: start.line, column: start.column, text: this.textFrom(start) }
  }

  scanRawString(start) {
    this.advance()
    this.advance()
    let value = ''
    for (;;) {
      if (this.done) throw this.error(start, 'unterminated string')
      const c = this.advance()
      if (c === '"') {
        return { kind: 'rawstring', line: start.line, column: start.column, value }
      }
      value += c
    }
  }

  scanString(start) {
    this.advance()
    let value = ''
    for (;;) {
      if (this.done) throw this.error(start, 'unterminated string')
      if (this.peek() === '\n') throw this.error(this.mark(), 'newline in string')
      if (this.peek() === '"') {
        this.advance()
        return { kind: 'string', line: start.line, column: start.column, value }
      }
      if (this.peek() === '\\') {
        value += this.scanEscape(start)
        continue
      }
      value += this.advance()
    }
  }

  scanEscape(stringStart) {
    const at = this.mark()
    this.advance()
    if (this.done) throw this.error(stringStart, 'unterminated string')
    if (this.peek() === '\n') throw this.error(this.mark(), 'newline in string')
    const c = this.advance()
    const invalid = () => this.error(at, `invalid escape \\${c}`)

    switch (c) {
      case 'n': return '\n'
      case 't': return '\t'
      case 'r': return '\r'
      case '\\': return '\\'
      case '"': return '"'
      case '0': return '\0'
      case 'x': {
        if (!isHexDigit(this.peek()) || !isHexDigit(this.peek(1))) throw invalid()
        const digits = this.advance() + this.advance()
        return String.fromCharCode(parseInt(digits, 16))
      }
      case 'u': {
        if (this.peek() !== '{') throw invalid()
        this.advance()
        let digits = ''
        while (isHexDigit(this.peek())) digits += this.advance()
        if (digits.length === 0 || this.peek() !== '}') throw invalid()
        this.advance()
        const code = parseInt(digits, 16)
        if (!Number.isFinite(code) || code > 0x10ffff) throw invalid()
        return String.fromCodePoint(code)
      }
      default:
        throw invalid()
    }
  }
}

export function scan(source) {
  return new Scanner(source).scan()
}

export const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']
"}

