    host = rest.slice(0, colon)
    port = rest.slice(colon + 1)
  }
  return { userinfo, host, port }
}

function buildAuthority({ userinfo, host, port }) {
  let out = ''
  if (userinfo !== undefined) out += userinfo + '@'
  out += host
  if (port !== undefined) out += ':' + port
  return out
}

/** Reassemble a component record into a URI reference. */
export function serialize(parts) {
  let out = ''
  if (parts.scheme !== undefined) out += parts.scheme + ':'
  if (parts.authority !== undefined) out += '//' + parts.authority
  out += parts.path
  if (parts.query !== undefined) out += '?' + parts.query
  if (parts.fragment !== undefined) out += '#' + parts.fragment
  return out
}

function isTruncatedPercent(text) {
  for (let i = 0; i < text.length; i += 1) {
    if (text[i] !== '%') continue
    const a = text[i + 1]
    const b = text[i + 2]
    if (a === undefined || b === undefined || !HEX.test(a) || !HEX.test(b)) {
      return true
    }
    i += 2
  }
  return false
}

/**
 * Check every component of a reference for a truncated percent-encoding.
 * Returns the name of the offending component, or `undefined`.
 */
export function findTruncatedPercent(text) {
  const parts = parse(text)
  const authority =
    parts.authority === undefined ? undefined : parseAuthority(parts.authority)
  const checks = [
    ['path', parts.path],
    ['userinfo', authority && authority.userinfo],
    ['host', authority && authority.host],
    ['query', parts.query],
    ['fragment', parts.fragment],
  ]
  for (const [name, value] of checks) {
    if (typeof value === 'string' && isTruncatedPercent(value)) return name
  }
  return undefined
}

const UNRESERVED = /[A-Za-z0-9\-._~]/

function normalizePercent(text) {
  let out = ''
  for (let i = 0; i < text.length; i += 1) {
    const c = text[i]
    if (c !== '%') {
      out += c
      continue
    }
    const hex = (text[i + 1] + text[i + 2]).toUpperCase()
    const decoded = String.fromCharCode(parseInt(hex, 16))
    out += UNRESERVED.test(decoded) ? decoded : '%' + hex
    i += 2
  }
  return out
}

function lowerAscii(text) {
  let out = ''
  for (const c of text) {
    out += c >= 'A' && c <= 'Z' ? c.toLowerCase() : c
  }
  return out
}

/** RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output = output.slice(0, Math.max(0, output.lastIndexOf('/')))
    } else if (input === '/..') {
      input = '/'
      output = output.slice(0, Math.max(0, output.lastIndexOf('/')))
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let end = input.indexOf('/', 1)
      if (end === -1) end = input.length
      output += input.slice(0, end)
      input = input.slice(end)
    }
  }
  return output
}

/** Normalize the components of a parsed reference. */
export function normalizeParts(parts) {
  const result = { ...parts }

  if (result.scheme !== undefined) result.scheme = lowerAscii(result.scheme)

  if (result.authority !== undefined) {
    const auth = parseAuthority(result.authority)
    if (auth.userinfo !== undefined) auth.userinfo = normalizePercent(auth.userinfo)
    auth.host = lowerAscii(normalizePercent(auth.host))
    if (auth.port !== undefined) {
      const fallback = result.scheme === undefined ? undefined : DEFAULT_PORTS[result.scheme]
      if (auth.port === '' || (fallback !== undefined && auth.port === fallback)) {
        auth.port = undefined
      }
    }
    result.authority = buildAuthority(auth)
  }

  result.path = normalizePercent(result.path)
  if (result.query !== undefined) result.query = normalizePercent(result.query)
  if (result.fragment !== undefined) result.fragment = normalizePercent(result.fragment)

  result.path = removeDotSegments(result.path)
  if (result.authority !== undefined && result.path === '') result.path = '/'

  return result
}

/** Normalize a URI reference given as text. */
export function normalize(text) {
  return serialize(normalizeParts(parse(text)))
}

function merge(base, refPath) {
  if (base.authority !== undefined && base.path === '') return '/' + refPath
  const cut = base.path.lastIndexOf('/')
  if (cut === -1) return refPath
  return base.path.slice(0, cut + 1) + refPath
}

/** RFC 3986 section 5.2.2, strict, followed by normalization. */
export function resolve(baseText, refText) {
  const base = parse(baseText)
  const ref = parse(refText)
  const target = {}

  if (ref.scheme !== undefined) {
    target.scheme = ref.scheme
    target.authority = ref.authority
    target.path = removeDotSegments(ref.path)
    target.query = ref.query
  } else {
    if (ref.authority !== undefined) {
      target.authority = ref.authority
      target.path = removeDotSegments(ref.path)
      target.query = ref.query
    } else {
      if (ref.path === '') {
        target.path = base.path
        target.query = ref.query !== undefined ? ref.query : base.query
      } else {
        if (ref.path.startsWith('/')) {
          target.path = removeDotSegments(ref.path)
        } else {
          target.path = removeDotSegments(merge(base, ref.path))
        }
        target.query = ref.query
      }
      target.authority = base.authority
    }
    target.scheme = base.scheme
  }
  target.fragment = ref.fragment

  return serialize(normalizeParts(target))
}
