{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { normalize, resolve, parse, findTruncatedPercent } from './uri.js'

function fail(message) {
  process.stderr.write('error: ' + message + '\n')
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function splitRecords(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'normalize' && argv[0] !== 'resolve')) {
    fail('usage: cli.js normalize|resolve')
  }
  const mode = argv[0]
  const records = splitRecords(readStdin())
  const out = []

  for (let i = 0; i < records.length; i += 1) {
    const n = i + 1
    const record = records[i]
    if (mode === 'normalize') {
      const bad = findTruncatedPercent(record)
      if (bad) fail(`line ${n}: the ${bad} has a truncated percent-encoding`)
      out.push(normalize(record))
      continue
    }
    const space = record.indexOf(' ')
    if (space === -1) fail(`line ${n}: expected a base and a reference`)
    const baseText = record.slice(0, space)
    const refText = record.slice(space + 1)
    if (parse(baseText).scheme === undefined) fail(`line ${n}: the base has no scheme`)
    const badBase = findTruncatedPercent(baseText)
    if (badBase) fail(`line ${n}: the ${badBase} has a truncated percent-encoding`)
    const badRef = findTruncatedPercent(refText)
    if (badRef) fail(`line ${n}: the ${badRef} has a truncated percent-encoding`)
    out.push(resolve(baseText, refText))
  }

  process.stdout.write(out.map((line) => line + '\n').join(''))
}

main()
"}

